	"≥": "\\ge ",
	"≠": "\\ne ",
	"±": "\\pm ",
	"∞": "\\infty ",
	"·": "\\cdot ",
	"−": "-",
	"–": "-",
	"⌊": "\\lfloor ",
	"⌋": "\\rfloor ",
	"⌈": "\\lceil ",
	"⌉": "\\rceil ",
	"∑": "\\sum ",
	"∏": "\\prod ",
	"→": "\\to ",
